text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "2026年华东地区已完成订单销售额城市排名",
      "business_question": "分析2026年华东地区已完成订单的销售额，按城市汇总并降序排名取前三名",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心业务问题（2026年华东已完成订单销售额Top3城市），直接支持决策目标。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04",
        "C05"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "华东"
              },
              {
                "field": "field_0004",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "order_year"
          }
        },
        {
          "step_id": "S03",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "order_year",
                "operator": "eq",
                "value": 2026
              }
            ]
          }
        },
        {
          "step_id": "S04",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S05",
          "operation": "top_n",
          "params": {
            "field": "total_sales",
            "direction": "desc",
            "n": 3
          }
        }
      ]
    }
  ]
}
